import hashlib
import hmac
import time
import os
import json
import sqlite3
import secrets
from functools import wraps
from flask import Flask, request, jsonify, g, abort

app = Flask(__name__)
app.config['SECRET_KEY'] = os.environ.get('APP_SECRET_KEY', secrets.token_hex(32))
app.config['DATABASE'] = os.environ.get('DB_PATH', '/var/app/data/users.db')

# Role hierarchy: higher number = more privilege
ROLE_HIERARCHY = {
    'guest': 0,
    'user': 1,
    'moderator': 2,
    'admin': 3,
    'superadmin': 4
}

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(app.config['DATABASE'])
        g.db.row_factory = sqlite3.Row
        g.db.execute('PRAGMA journal_mode=WAL')
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def constant_time_compare(a, b):
    """Constant-time string comparison to prevent timing attacks."""
    return hmac.compare_digest(a.encode('utf-8'), b.encode('utf-8'))

def generate_session_token(user_id, role, timestamp):
    """Generate HMAC-based session token."""
    message = f"{user_id}:{role}:{timestamp}"
    return hmac.new(
        app.config['SECRET_KEY'].encode('utf-8'),
        message.encode('utf-8'),
        hashlib.sha256
    ).hexdigest()

def validate_session(token_header):
    """Parse and validate session token from header."""
    if not token_header or '.' not in token_header:
        return None

    parts = token_header.split('.')
    if len(parts) != 4:
        return None

    user_id, role, timestamp, signature = parts

    # Check token freshness (24 hour expiry)
    try:
        token_time = int(timestamp)
    except ValueError:
        return None

    if abs(time.time() - token_time) > 86400:
        return None

    # Validate role is known
    if role not in ROLE_HIERARCHY:
        return None

    # Verify HMAC signature
    expected = generate_session_token(user_id, role, timestamp)
    if not constant_time_compare(expected, signature):
        return None

    return {'user_id': user_id, 'role': role, 'timestamp': token_time}

def requires_role(minimum_role):
    """Decorator that enforces minimum role level for endpoint access.

    Uses role hierarchy comparison to ensure the authenticated user
    has sufficient privileges. The check ensures the user's role level
    meets or exceeds the required minimum.
    """
    def decorator(f):
        @wraps(f)
        def decorated_function(*args, **kwargs):
            token_header = request.headers.get('X-Session-Token')
            session = validate_session(token_header)

            if session is None:
                abort(401)

            user_role_level = ROLE_HIERARCHY.get(session['role'], 0)
            required_level = ROLE_HIERARCHY.get(minimum_role, 0)

            # Authorization check: user's role level must meet minimum
            if user_role_level < required_level:
                abort(403)

            g.current_user = session
            return f(*args, **kwargs)
        return decorated_function
    return decorator

def requires_exact_role(role_name):
    """Decorator that enforces exact role match for sensitive operations.

    Unlike requires_role which checks hierarchy, this ensures the user
    has the SPECIFIC role required - used for operations where even
    higher-privileged users should use dedicated endpoints.
    """
    def decorator(f):
        @wraps(f)
        def decorated_function(*args, **kwargs):
            token_header = request.headers.get('X-Session-Token')
            session = validate_session(token_header)

            if session is None:
                abort(401)

            # Exact role match required
            if session['role'] != role_name:
                abort(403)

            g.current_user = session
            return f(*args, **kwargs)
        return decorated_function
    return decorator

@app.route('/api/users', methods=['GET'])
@requires_role('moderator')
def list_users():
    """List all users - requires moderator or above."""
    db = get_db()
    users = db.execute(
        'SELECT id, username, email, role, created_at FROM users'
    ).fetchall()
    return jsonify([dict(u) for u in users])

@app.route('/api/users/<int:user_id>/role', methods=['PUT'])
@requires_role('admin')
def update_user_role(user_id):
    """Update a user's role - requires admin or above."""
    data = request.get_json()
    if not data or 'role' not in data:
        abort(400)

    new_role = data['role']
    if new_role not in ROLE_HIERARCHY:
        abort(400)

    # Privilege escalation prevention: cannot assign role higher than own
    current_user_level = ROLE_HIERARCHY.get(g.current_user['role'], 0)
    target_role_level = ROLE_HIERARCHY.get(new_role, 0)

    if target_role_level >= current_user_level:
        abort(403)

    db = get_db()
    db.execute(
        'UPDATE users SET role = ? WHERE id = ?',
        (new_role, user_id)
    )
    db.commit()
    return jsonify({'status': 'updated', 'user_id': user_id, 'new_role': new_role})

@app.route('/api/system/config', methods=['GET'])
@requires_exact_role('superadmin')
def get_system_config():
    """Get system configuration - superadmin only."""
    config = {
        'database': app.config['DATABASE'],
        'max_users': 10000,
        'features': ['audit_log', 'mfa', 'ip_whitelist']
    }
    return jsonify(config)

@app.route('/api/admin/audit', methods=['GET'])
@requires_role('admin')
def get_audit_log():
    """Get audit log entries - requires admin."""
    db = get_db()
    limit = min(int(request.args.get('limit', 100)), 1000)
    entries = db.execute(
        'SELECT * FROM audit_log ORDER BY created_at DESC LIMIT ?',
        (limit,)
    ).fetchall()
    return jsonify([dict(e) for e in entries])

@app.route('/api/admin/delete-user', methods=['DELETE'])
@requires_role('admin')
def delete_user():
    """Delete a user account - requires admin."""
    data = request.get_json()
    if not data or 'user_id' not in data:
        abort(400)

    target_id = data['user_id']

    # Cannot delete yourself
    if str(target_id) == g.current_user['user_id']:
        abort(400)

    db = get_db()

    # Check target user's role - cannot delete equal or higher role
    target = db.execute(
        'SELECT role FROM users WHERE id = ?', (target_id,)
    ).fetchone()

    if target is None:
        abort(404)

    target_level = ROLE_HIERARCHY.get(target['role'], 0)
    current_level = ROLE_HIERARCHY.get(g.current_user['role'], 0)

    if target_level >= current_level:
        abort(403)

    db.execute('DELETE FROM users WHERE id = ?', (target_id,))
    db.commit()

    # Audit log
    db.execute(
        'INSERT INTO audit_log (action, actor_id, target_id, details) VALUES (?, ?, ?, ?)',
        ('delete_user', g.current_user['user_id'], target_id, json.dumps({'role': target['role']}))
    )
    db.commit()
    return jsonify({'status': 'deleted'})

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=8080, debug=False)
